def repl(p,old,new):
 s=p.read_text()
 if s.count(old)!=1: raise RuntimeError(f"ambiguous patch {p}: {old[:80]!r}")
 p.write_text(s.replace(old,new,1))

def patch_text_settings():
 p=ROOT/'src/activities/settings/TextSettingsActivity.h'
 repl(p,'Tab initialTab = Tab::Family);','Tab initialTab = Tab::Family, bool wikiMode = false);')
 repl(p,'return static_cast<int>(Tab::Count);','return wikiMode_ ? 3 : static_cast<int>(Tab::Count);')
 repl(p,'  Tab tab_;','  Tab tab_;\n  bool wikiMode_ = false;')
 p=ROOT/'src/activities/settings/TextSettingsActivity.cpp'
 repl(p,'const SdCardFontRegistry* registry, Tab initialTab)','const SdCardFontRegistry* registry, Tab initialTab, bool wikiMode)')
 repl(p,'registry_(registry), tab_(initialTab) {}','registry_(registry), tab_(wikiMode && initialTab == Tab::Style ? Tab::Family : initialTab), wikiMode_(wikiMode) {}')
 repl(p,'  if (optionPopup_.isActive()) return;\n  if (tab_ != static_cast<Tab>(index))','  if (optionPopup_.isActive() || index < 0 || index >= tabCount()) return;\n  if (tab_ != static_cast<Tab>(index))')
 s=p.read_text();s=s.replace('% static_cast<int>(Tab::Count)', '% tabCount()');s=s.replace('constexpr int count = static_cast<int>(Tab::Count);','const int count = tabCount();');s=s.replace('previewHeight, familyName, sizeName);','previewHeight, familyName, sizeName, wikiMode_);');p.write_text(s)
 p=ROOT/'src/activities/settings/TextSettingsPreview.h'
 repl(p,'const char* familyName, const char* sizeName);','const char* familyName, const char* sizeName, bool wikiMode = false);')
 p=ROOT/'src/activities/settings/TextSettingsPreview.cpp'
 repl(p,'int fontId, int textWidth) {','int fontId, int textWidth, bool wikiMode) {')
 s=p.read_text();s=s.replace('SETTINGS.hyphenationEnabled != 0,\n                    SETTINGS.focusReadingEnabled != 0, style);','!wikiMode && SETTINGS.hyphenationEnabled != 0,\n                    !wikiMode && SETTINGS.focusReadingEnabled != 0, style);').replace('const char* familyName, const char* sizeName) {','const char* familyName, const char* sizeName, bool wikiMode) {').replace('.focusReading = SETTINGS.focusReadingEnabled != 0,','.focusReading = !wikiMode && SETTINGS.focusReadingEnabled != 0,').replace('.hyphenation = SETTINGS.hyphenationEnabled != 0}', '.hyphenation = !wikiMode && SETTINGS.hyphenationEnabled != 0}').replace('SETTINGS.focusReadingEnabled ? 0x03 : 0x01','(!wikiMode && SETTINGS.focusReadingEnabled) ? 0x03 : 0x01').replace('relayout(layout, renderer, fontId, textWidth);','relayout(layout, renderer, fontId, textWidth, wikiMode);');p.write_text(s)

def main():
 for name,digest in EXPECTED.items():
  p=ROOT/name;actual=hashlib.sha256(p.read_bytes()).hexdigest()
  if actual!=digest: raise RuntimeError(f"{name}: beta 3 refuses unknown input {actual}")
 patch_text_settings()
 for name,encoded in PAYLOAD.items():
  data=zlib.decompress(base64.b85decode(encoded));p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
 print('Applied guarded beta 3 patch.')
if __name__=='__main__':main()
